('913c3794-3ffc-5888-8f69-414113a44341', 'matrix_entry', 'entry_span_01', '{"id": "entry_span_01", "type": "matrix_entry", "label": "SPAN-01", "layer": 5, "indexed_asset": "SPAN-01", "function_tag": "Span", "function_definition": "Span (Bridges gaps between separated points or parties)", "outcome_number": "01", "outcome_label": "Opening Gambit", "outcome_behavior": "initiates", "rank": "Prime", "phase": "Initiation", "actionable_statement": "Deploy to make first contact between two isolated parties who don''t yet know they need each other. Span-01 is the cold introduction that becomes the only route through.", "symbol_status": "physical", "svg_phase_symbol_id": "span-initiation", "svg_object_symbol_id": "span-emblem", "object_id": "tri_key_clasp", "svg_phase_data_uri": "data:image/svg+xml;base64,", "svg_object_data_uri": "data:image/svg+xml;base64,"}'::jsonb, now() - interval '2 hours'),
