-- ==========================================================================
-- Complete Ledger Set Seed (250 Nodes, 501 Edges, 90 Matrix, 18 Glyphs, 6 Emblems)
-- Sole seed of the substrate. Symbol-centric representation.
-- Topological Layers 0-6 enforced. Index functions are immutable rank surfaces.
-- ==========================================================================

BEGIN;

-- 1. NODES INSERTION (250 Nodes)
ON CONFLICT (id) DO UPDATE SET props = EXCLUDED.props, external_ref = EXCLUDED.external_ref, node_type = EXCLUDED.node_type;

-- 2. EDGES INSERTION (501 Edges)
ON CONFLICT (id) DO NOTHING;

-- 3. EVENTS INSERTION (Append-only occurrence log)
ON CONFLICT (event_id) DO NOTHING;

-- 4. BUCKET CONSTRAINTS
ON CONFLICT (bucket_name, version) DO UPDATE SET constraint_body = EXCLUDED.constraint_body;

-- 5. FRAGMENT RECOGNITION

DO $$
DECLARE
    root_nid UUID := '7a7cda4c-d42d-5cf2-afb6-060ebaf6b82b';
    frag_id  UUID;
BEGIN
    VALUES (root_nid, NULL, 1, '{"title":"The Ledger Set / Typhen Root Fragment","seed":true,"matrix_entries":90,"glyph_count":18,"emblem_count":6}'::jsonb)
    ON CONFLICT (root_node_id) DO UPDATE SET props = EXCLUDED.props
    RETURNING id INTO frag_id;
END $$;

-- 6. BUILD PROJECTIONS

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'replay_ledger_projection') THEN
        PERFORM replay_ledger_projection();
    END IF;
END $$;

COMMIT;
